source.patch:
From 22f12ce58eb5f41d23bb205530034b29aac03700 Mon Sep 17 00:00:00 2001
From: Nick Wellnhofer <wellnhofer@aevum.de>
Date: Fri, 18 Mar 2022 15:03:44 +0100
Subject: [PATCH] Stop calling deprecated libxml2 init functions

---
 libxslt/transform.c | 1 -
 python/libxslt.c    | 1 -
 tests/fuzz/fuzz.c   | 1 -
 xsltproc/xsltproc.c | 1 -
 4 files changed, 4 deletions(-)

diff --git a/libxslt/transform.c b/libxslt/transform.c
index 57f05bf..2d8fd7f 100644
--- a/libxslt/transform.c
+++ b/libxslt/transform.c
@@ -637,7 +637,6 @@ xsltNewTransformContext(xsltStylesheetPtr style, xmlDocPtr doc) {
     cur->prof = 0;

     cur->style = style;
-    xmlXPathInit();
     cur->xpathCtxt = xmlXPathNewContext(doc);
     if (cur->xpathCtxt == NULL) {
 	xsltTransformError(NULL, NULL, (xmlNodePtr) doc,
diff --git a/python/libxslt.c b/python/libxslt.c
index 685e49d..353939e 100644
--- a/python/libxslt.c
+++ b/python/libxslt.c
@@ -1279,7 +1279,6 @@ void initlibxsltmod(void) {
      * Specific XSLT initializations
      */
     libxslt_xsltErrorInitialize();
-    xmlInitMemory();
     xmlLoadExtDtdDefaultValue = XML_DETECT_IDS | XML_COMPLETE_ATTRS;
     xmlDefaultSAXHandler.cdataBlock = NULL;
     /*
diff --git a/tests/fuzz/fuzz.c b/tests/fuzz/fuzz.c
index 780c2d4..cf1e238 100644
--- a/tests/fuzz/fuzz.c
+++ b/tests/fuzz/fuzz.c
@@ -53,7 +53,6 @@ static void
 xsltFuzzInit(void) {
     /* Init libxml2, libxslt and libexslt */
     xmlInitParser();
-    xmlXPathInit();
     xsltInit();
     exsltRegisterAll();

diff --git a/xsltproc/xsltproc.c b/xsltproc/xsltproc.c
index eec57bc..5fd3a29 100644
--- a/xsltproc/xsltproc.c
+++ b/xsltproc/xsltproc.c
@@ -565,7 +565,6 @@ main(int argc, char **argv)
     }

     srand(time(NULL));
-    xmlInitMemory();

 #if defined(_WIN32) && !defined(__CYGINW__)
     setmode(fileno(stdout), O_BINARY);
-- 
2.43.0
